$('export').onclick=()=>{const rows=[['Stock','Expiry','Strike','Type','Side','Lots','Lot size','Units','ATP','LTP or exit','Realized','Unrealized','Total PnL','Status'],...positions.map(p=>{const value=p.closed?p.exit:mark(p),pnl=(value-p.atp)*p.lots*p.lotSize*p.side;return[p.symbol,new Date(p.expiry).toISOString(),p.strike,p.type,p.side===1?'BUY':'SELL',p.lots,p.lotSize,p.lots*p.lotSize,p.atp,value,p.closed?pnl:0,p.closed?0:pnl,pnl,p.closed?'CLOSED':'OPEN'];})],quote=v=>'"'+String(v).replace(/"/g,'""')+'"',blob=new Blob([rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='stock-options-positions.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
